const item = $input.first().json ?? {};

const firstName = String(item.firstName ?? '').trim();
const lastName = String(item.lastName ?? '').trim();
const contactName = [firstName, lastName].filter(Boolean).join(' ').trim();

const email = String(item.email ?? '').trim();
const senderEmail = contactName && email ? `${contactName} <${email}>` : email;

const subject = String(item.lastEmailSubject ?? item.subject ?? '').trim();
const urgencyScoreRaw = item.urgencyScore ?? item.urgency_score ?? 0;
const urgencyScore = Number(urgencyScoreRaw);

const budgetMentionedRaw = item.budgetMentioned ?? item.budget_mentioned ?? false;
const budgetMentioned =
  typeof budgetMentionedRaw === 'string'
    ? budgetMentionedRaw.toLowerCase() === 'true'
    : Boolean(budgetMentionedRaw);

const matchedIn = Array.isArray(item.matchedIn) ? item.matchedIn : [];
const prefillAccount = item.prefillAccount && typeof item.prefillAccount === 'object' ? item.prefillAccount : {};
const matchedAccountId = String(item.matchedAccountId ?? item.matched_account_id ?? prefillAccount.id ?? '').trim();
const matchedAccountName = String(item.matchedAccountName ?? item.matched_account_name ?? prefillAccount.name ?? '').trim();
const matchedAccountWebsite = String(item.matchedAccountWebsite ?? item.matched_account_website ?? prefillAccount.website ?? '').trim();
const accountFound = Boolean(item.accountFound) || Boolean(matchedAccountId) || matchedIn.includes('Account');
const accountName = String(item.account_name ?? matchedAccountName ?? prefillAccount.name ?? item.company ?? item.org_name ?? '').trim();

// The dashboard uses message_id or id to set source_message_id for dedup/upsert.
const messageId = String(item.message_id ?? item.id ?? (email ? `${email}|${subject}` : `unknown|${subject}`));

return [
  {
    json: {
      message_id: messageId,
      contact_name: contactName,
      org_name: String(item.company ?? item.org_name ?? '').trim(),
      sender_email: senderEmail,
      sender_domain: String(item.emailDomain ?? item.sender_domain ?? '').trim(),
      subject: subject,
      sentiment: String(item.sentiment ?? 'Unknown'),
      confidence: String(item.sentimentConfidence ?? item.confidence ?? 'N/A'),
      primary_topic: String(item.primaryTopic ?? item.primary_topic ?? '').trim(),
      secondary_topics: String(item.secondaryTopics ?? item.secondary_topics ?? '').trim(),
      intent: String(item.leadIntent ?? item.intent ?? '').trim(),
      urgency_score: Number.isFinite(urgencyScore) ? Math.max(0, Math.min(10, urgencyScore)) : 0,
      budget_mentioned: budgetMentioned,
      event_referenced: String(item.eventReferenced ?? item.event_referenced ?? '').trim(),
      suggested_action: String(item.suggestedAction ?? item.suggested_action ?? '').trim(),
      existsInSalesforce: Boolean(item.existsInSalesforce),
      matchedIn,
      reason: String(item.reason ?? '').trim(),
      accountFound,
      salesforce_mode: accountFound ? 'create_contact_under_existing_account' : 'create_account_then_contact',
      matchedAccountId,
      matchedAccountName,
      matchedAccountWebsite,
      account_name: accountName,
      prefillAccount: {
        ...prefillAccount,
        id: matchedAccountId || prefillAccount.id || '',
        name: accountName || matchedAccountName || prefillAccount.name || '',
        website: matchedAccountWebsite || prefillAccount.website || '',
      },
      emailBody: String(item.emailBody ?? ''),
      phone_number: (() => {
        const raw = String(item.phone_number ?? '').trim();
        // Strip leading country code (+XX or 00XX) to get the local number
        return raw.replace(/^(?:\+\d{1,3}|00\d{1,3})[\s\-.]?/, '').replace(/[\s\-.]/g, '');
      })(),
      phone_country_code: (() => {
        const raw = String(item.phone_number ?? '').trim();
        const match = raw.match(/^(\+\d{1,3}|00\d{1,3})/);
        if (match) return match[1].replace(/^00/, '+');
        return '';
      })(),
      industry: String(item.industry ?? 'diverse').trim(),
      contact_title: String(item.contact_title ?? item.title ?? '').trim(),
      contact_gender: (() => {
        const g = String(item.contact_gender ?? item.contactGender ?? '').trim().toLowerCase();
        return g === 'man' || g === 'vrouw' ? g : '';
      })(),
      matchedAccountCandidates: Array.isArray(item.matchedAccountCandidates) ? item.matchedAccountCandidates : [],
    },
  },
];

const input = $input.first().json;
const body = input.body && typeof input.body === 'object' ? input.body : input;
const contact = body.contact && typeof body.contact === 'object' ? body.contact : {};

const rawGender = String(contact.gender ?? body.contact_gender ?? input.contact_gender ?? '').trim().toLowerCase();
const contactGender = rawGender === 'man' || rawGender === 'vrouw' ? rawGender : '';
const salutation = contactGender === 'man' ? 'Mr.' : (contactGender === 'vrouw' ? 'Ms.' : '');

return [{
  json: {
    ...input,
    ...body,
    contact_gender: contactGender,
    salutation,
    contact: {
      ...contact,
      gender: contactGender,
    },
    save_source: 'dashboard',
    save_received_at: new Date().toISOString(),
  },
}];

try {
  const item = $input.first().json ?? {};
  const rawCompany = String(item.company ?? item.org_name ?? '').trim();

  const add = (set, value) => {
    const clean = String(value ?? '').replace(/\s+/g, ' ').trim();
    if (clean) set.add(clean);
  };

  const variants = new Set();
  const normalizedSpaces = rawCompany
    .replace(/[._/\\]+/g, ' ')
    .replace(/[-\u2013\u2014]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();

  add(variants, rawCompany);
  add(variants, normalizedSpaces);

  // Try without common legal suffixes (BVBA/BV/NV/...) so we can match SF accounts like
  // "Resourcefull Houthalen" even if the inbound company includes "BVBA".
  if (normalizedSpaces) {
    const stripped = normalizedSpaces
      .replace(/\b(?:bvba|bv|nv|sa|srl|sprl|gmbh|ag|ltd|limited|inc|llc|plc|kg|oy|ab)\b\.?/gi, ' ')
      .replace(/\s+/g, ' ')
      .trim();
    add(variants, stripped);
  }

  if (normalizedSpaces) {
    const words = normalizedSpaces.split(' ').filter(Boolean);
    add(variants, words.join(' '));
    add(variants, words.join('-'));
    add(variants, words.join(''));
    add(variants, words.join('.'));
  }

  const asciiCompact = rawCompany
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^A-Za-z0-9]/g, '');
  add(variants, asciiCompact);

  const companyVariants = [...variants].filter(Boolean).slice(0, 12);

  try {
    const data = $getWorkflowStaticData('global');
    data.sfAccountSearchResults = [];
  } catch (e) {
    // Static data can be unavailable in some task-runner contexts; normalization has a fallback.
  }

  return [{
    json: {
      ...item,
      companyVariants,
    },
  }];
} catch (error) {
  return [{ json: { companyVariants: [], sfVariantBuildError: String(error.message ?? error) } }];
}

const item = $input.first().json ?? {};
const variants = Array.isArray(item.companyVariants) ? item.companyVariants : [];
const outputVariants = variants.length ? variants : [''];

return outputVariants.map((companyVariant, index) => ({
  json: {
    ...item,
    companyVariant,
    companyVariantIndex: index,
  },
}));

