={{ (() => {
  let v = String($json.companyVariant ?? '').trim().replace(/[%_]/g, ' ').replace(/\s+/g, ' ').trim();
  let d = String($json.emailDomain ?? $json.sender_domain ?? '').trim().toLowerCase();

  if (v) v = v.replace(/'/g, "''");
  if (d) d = d.replace(/'/g, "''");

  const clauses = [];
  if (v) clauses.push("Name LIKE '%" + v + "%' ");
  if (d) clauses.push("Website LIKE '%" + d + "%' ");

  if (!clauses.length) return 'SELECT Id, Name, Website FROM Account LIMIT 0';

  return (
    'SELECT Id, Name, Website FROM Account WHERE ' +
    clauses.join(' OR ') +
    ' LIMIT 25'
  );
})() }}

