// Prepare analytics row from enriched email data
// $input comes from Extract Email Intelligence
const item = $input.first().json;

// Sentiment data â€” try direct property first, then upstream node reference
let sentimentCategory = 'Unknown';
let sentimentConfidence = 'N/A';
try {
  if (item.sentimentAnalysis) {
    sentimentCategory = item.sentimentAnalysis.category || 'Unknown';
    sentimentConfidence = String(item.sentimentAnalysis.confidence || 'N/A');
  } else {
    const sentimentNode = $('Analyze Email Sentiment').first().json;
    sentimentCategory = sentimentNode.sentimentAnalysis?.category || 'Unknown';
    sentimentConfidence = String(sentimentNode.sentimentAnalysis?.confidence || 'N/A');
  }
} catch (e) {
  // Fallback â€” sentiment data not available
}

// Gmail data â€” handle from field as string OR object
let fromField = '';
let subject = '';
try {
  // Try to get from the input item first
  let rawFrom = item.from || null;
  let rawSubject = item.subject || '';

  // If not on input, try the Get Full Email node
  if (!rawFrom) {
    const gmail = $('Get Full Email').first().json;
    rawFrom = gmail.from || '';
    rawSubject = gmail.subject || '';
  }

  // Handle from field: could be string "Name <email>" or object {name, email}
  if (typeof rawFrom === 'object' && rawFrom !== null) {
    // Object format: {name: "John Doe", email: "user@example.com"}
    if (rawFrom.email) {
      fromField = rawFrom.name ? `${rawFrom.name} <${rawFrom.email}>` : rawFrom.email;
    } else if (rawFrom.value && Array.isArray(rawFrom.value)) {
      // Some email parsers return {value: [{address: "...", name: "..."}]}
      const first = rawFrom.value[0];
      fromField = first ? (first.name ? `${first.name} <${first.address}>` : first.address || '') : '';
    } else {
      fromField = JSON.stringify(rawFrom);
    }
  } else {
    fromField = String(rawFrom || '');
  }

  subject = String(rawSubject || '');
} catch (e) {
  // Fallback â€” gmail data not available
}

// Extract domain from email â€” fromField is guaranteed to be a string now
const domainMatch = fromField.match(/@([^>\s]+)/);

return [{
  json: {
    timestamp: new Date().toISOString(),
    sentiment: sentimentCategory,
    confidence: sentimentConfidence,
    sender_email: fromField,
    sender_domain: domainMatch ? domainMatch[1] : '',
    subject: subject,
    primary_topic: String(item.primary_topic || item.output?.primary_topic || ''),
    secondary_topics: String(item.secondary_topics || item.output?.secondary_topics || ''),
    intent: String(item.intent || item.output?.intent || ''),
    urgency_score: Number(item.urgency_score || item.output?.urgency_score || 0),
    org_name: String(item.org_name || item.output?.org_name || ''),
    contact_name: String(item.contact_name || item.output?.contact_name || ''),
    budget_mentioned: String(item.budget_mentioned ?? item.output?.budget_mentioned ?? false),
    event_referenced: String(item.event_referenced || item.output?.event_referenced || ''),
    suggested_action: String(item.suggested_action || item.output?.suggested_action || ''),
    phone_number: String(item.phone_number || item.output?.phone_number || ''),
    contact_title: String(item.contact_title || item.output?.contact_title || ''),
    contact_gender: String(item.contact_gender || item.output?.contact_gender || ''),
    industry: String(item.industry || item.output?.industry || 'diverse'),
    week_number: getWeekNumber(new Date())
  }
}];

function getWeekNumber(d) {
  const date = new Date(Date.UTC(d.getFullYear(), d.getMonth(), d.getDate()));
  const dayNum = date.getUTCDay() || 7;
  date.setUTCDate(date.getUTCDate() + 4 - dayNum);
  const yearStart = new Date(Date.UTC(date.getUTCFullYear(), 0, 1));
  return Math.ceil((((date - yearStart) / 86400000) + 1) / 7);
}

// Prepare CRM data for Salesforce upsert
const item = $input.first().json;

// Capture full email body for dashboard display
let emailBody = '';
try {
  const fullEmail = $('Get Full Email').first().json;
  emailBody = fullEmail.text || fullEmail.snippet || '';
} catch (e) {
  // Email body not available
}

// Extract clean email from "Name <email>" format or object
let cleanEmail = item.sender_email || '';
if (typeof cleanEmail === 'object') {
  cleanEmail = cleanEmail.email || cleanEmail.address || JSON.stringify(cleanEmail);
}
cleanEmail = String(cleanEmail);
const emailMatch = cleanEmail.match(/<([^>]+)>/);
if (emailMatch) cleanEmail = emailMatch[1];
else if (cleanEmail.includes('@')) cleanEmail = cleanEmail.trim();

// Split contact name into first + last
const fullName = String(item.contact_name || '').trim();
const nameParts = fullName.split(/\s+/).filter(Boolean);
const firstName = nameParts[0] || '';
const lastName = nameParts.length > 1 ? nameParts.slice(1).join(' ') : (nameParts[0] || 'Unknown');

// Extract phone number â€” AI-extracted value with regex fallback from email body
let phoneNumber = String(item.phone_number || '').trim();
if (!phoneNumber && emailBody) {
  const phoneMatch = emailBody.match(/(?:\+?[\d][\d\s\-().]{6,}[\d])/);
  if (phoneMatch) phoneNumber = phoneMatch[0].trim();
}

// Map sentiment to Salesforce Lead Rating
const ratingMap = { Positive: 'Hot', Neutral: 'Warm', Negative: 'Cold' };

// Determine if Opportunity should be created (hot leads only)
const urgency = Number(item.urgency_score) || 0;
const budgetMentioned = item.budget_mentioned === 'true';
const rawGender = String(item.contact_gender || '').trim().toLowerCase();
const contactGender = rawGender === 'man' || rawGender === 'vrouw' ? rawGender : '';
const salutation = contactGender === 'man' ? 'Mr.' : (contactGender === 'vrouw' ? 'Ms.' : '');

const createOpportunity = (item.sentiment === 'Positive' && urgency >= 7) || budgetMentioned;

return [{
  json: {
    // Standard Lead fields
    email: cleanEmail,
    firstName: firstName,
    lastName: lastName,
    company: String(item.org_name || item.sender_domain || 'Unknown'),
    leadRating: ratingMap[item.sentiment] || 'Warm',
    description: String(item.suggested_action || ''),
    // Custom fields for Salesforce
    sentiment: String(item.sentiment || 'Unknown'),
    sentimentConfidence: String(item.confidence || 'N/A'),
    primaryTopic: String(item.primary_topic || ''),
    leadIntent: String(item.intent || ''),
    urgencyScore: urgency,
    budgetMentioned: budgetMentioned,
    eventReferenced: String(item.event_referenced || ''),
    emailDomain: String(item.sender_domain || ''),
    lastEmailSubject: String(item.subject || ''),
    suggestedAction: String(item.suggested_action || ''),
    // Opportunity control flags
    createOpportunity: createOpportunity,
    opportunityName: createOpportunity
      ? (item.primary_topic || 'Inquiry') + ' â€” ' + (item.org_name || cleanEmail) + ' (Week ' + (item.week_number || '') + ')'
      : '',
    emailBody: emailBody,
    phone_number: phoneNumber,
    title: String(item.contact_title || ''),
    contact_title: String(item.contact_title || ''),
    contact_gender: contactGender,
    salutation: salutation,
    industry: String(item.industry || 'diverse')
  }
}];

try {
  const base = $('Prepare CRM Data').first().json ?? {};
  const norm = (s) => String(s ?? '').trim().toLowerCase();
  const baseEmail = norm(base.email);
  const firstName = String(base.firstName ?? '').trim();
  const lastName = String(base.lastName ?? '').trim();
  const company = String(base.company ?? '').trim();

  const isLeadHit = (j) => {
    const id = String(j.Id ?? '').trim();
    const em = norm(j.Email);
    return Boolean(id && em && baseEmail && em === baseEmail);
  };

  const isContactHit = (j) => {
    const id = String(j.Id ?? '').trim();
    const fn = String(j.FirstName ?? '').trim();
    const ln = String(j.LastName ?? '').trim();
    return Boolean(id && (fn || ln));
  };

  let leadResults = [];
  let contactResults = [];
  try {
    leadResults = $('SF Get Lead By Email2').all().map((i) => i.json).filter(isLeadHit);
  } catch (e) {
    leadResults = [];
  }
  try {
    contactResults = $('SF Get Contact By Name').all().map((i) => i.json).filter(isContactHit);
  } catch (e) {
    contactResults = [];
  }

  let accounts = [];
  try {
    const sd = $getWorkflowStaticData('global');
    const raw = Array.isArray(sd.sfAccountSearchResults) ? sd.sfAccountSearchResults : [];
    const seen = new Set();
    for (const a of raw) {
      const id = String(a.Id ?? '').trim();
      if (!id || seen.has(id)) continue;
      seen.add(id);
      accounts.push({
        Id: id,
        Name: String(a.Name ?? '').trim(),
        Website: String(a.Website ?? '').trim(),
      });
    }
  } catch (e) {
    accounts = [];
  }

  const existsInSalesforce = leadResults.length > 0 || contactResults.length > 0;
  const matchedIn = [];
  if (contactResults.length) matchedIn.push('Contact');
  if (leadResults.length) matchedIn.push('Lead');
  if (accounts.length) matchedIn.push('Account');

  const accountFound = accounts.length > 0;
  const best = accounts[0] || { Id: '', Name: '', Website: '' };
  const matchedAccountId = best.Id || '';
  const matchedAccountName = best.Name || '';
  const matchedAccountWebsite = best.Website != null ? String(best.Website) : '';

  const matchedAccountCandidates = accounts.map((a) => ({
    id: String(a.Id ?? '').trim(),
    name: String(a.Name ?? '').trim(),
    website: a.Website != null ? String(a.Website).trim() : '',
  })).filter((x) => x.id);

  const fullName = [firstName, lastName].filter(Boolean).join(' ').trim() || 'onbekende persoon';

  let reason = '';
  if (existsInSalesforce && accountFound && matchedAccountName) {
    reason = `Persoon gevonden (${matchedIn.filter((x) => x !== 'Account').join(' en ') || 'Contact/Lead'}) voor ${fullName}; Account '${matchedAccountName}' (${matchedAccountId}) gevonden.`;
  } else if (existsInSalesforce) {
    reason = `Contact of Lead gevonden voor ${fullName} (${matchedIn.filter((x) => x !== 'Account').join(', ')}).`;
  } else if (accountFound && matchedAccountName) {
    reason = `Account '${matchedAccountName}' gevonden via bedrijfsnaam-varianten, maar geen Contact of Lead gevonden voor ${fullName}. Persoon is nieuw.`;
  } else {
    reason = `Geen Account, Contact of Lead gevonden voor ${fullName}${company ? ` (${company})` : ''}.`;
  }

  return [
    {
      json: {
        ...base,
        existsInSalesforce,
        matchedIn,
        reason,
        accountFound,
        matchedAccountId,
        matchedAccountName,
        matchedAccountWebsite,
        matchedAccountCandidates,
        prefillAccount: {
          id: matchedAccountId,
          name: matchedAccountName,
          website: matchedAccountWebsite,
        },
      },
    },
  ];
} catch (error) {
  let base = {};
  try {
    base = $('Prepare CRM Data').first().json ?? {};
  } catch (e) {
    base = {};
  }
  return [
    {
      json: {
        ...base,
        existsInSalesforce: false,
        matchedIn: [],
        reason: `Fout bij Salesforce-duplicaatcheck: ${String(error.message ?? error)}`,
        accountFound: false,
        matchedAccountId: '',
        matchedAccountName: '',
        matchedAccountWebsite: '',
        matchedAccountCandidates: [],
        prefillAccount: { id: '', name: '', website: '' },
      },
    },
  ];
}

const staticData = $getWorkflowStaticData('global');
if (!Array.isArray(staticData.sfAccountSearchResults)) {
  staticData.sfAccountSearchResults = [];
}
const seen = new Set(staticData.sfAccountSearchResults.map((a) => String(a.Id ?? '').trim()).filter(Boolean));

for (const item of $input.all()) {
  const j = item.json ?? {};
  const id = String(j.Id ?? '').trim();
  const name = String(j.Name ?? '').trim();
  if (id && name && !seen.has(id)) {
    seen.add(id);
    staticData.sfAccountSearchResults.push({
      Id: id,
      Name: name,
      Website: String(j.Website ?? '').trim(),
    });
  }
}

return $input.all();
